I'm trying to create bidirectional infinite scroll example using maintainVisibleContentPosition prop, and right of the bat found issue, that when maintainVisibleContentPosition is enabled, i'm getting onEndReached triggered in the beginning of the list.
```
onStartReached {"distanceFromStart": 0}
onEndReached {"distanceFromEnd": -2770}
```
I think it has to do with additional offset, which is added when using maintainVisibleContentPosition. I didn't yet looked how it's working, and have no idea how to fix it.
Here is reproducer:

```
import { type Item, renderItem } from "@/app/cards-renderItem";
import { DO_SCROLL_TEST, DRAW_DISTANCE, ESTIMATED_ITEM_LENGTH } from "@/constants/constants";
import { useScrollTest } from "@/constants/useScrollTest";
import { LegendList, type LegendListRef } from "@legendapp/list";
import { useRef, useState } from "react";
import { LogBox, Platform, StyleSheet, Text, View } from "react-native";

LogBox.ignoreLogs(["Open debugger"]);

export default function Cards() {
    const listRef = useRef<LegendListRef>(null);

    const [data, setData] = useState<Item[]>(
        () =>
            Array.from({ length: 20 }, (_, i) => ({
                id: i.toString(),
            })) as any[],
    );

    if (DO_SCROLL_TEST) {
        useScrollTest((offset) => {
            listRef.current?.scrollToOffset({
                offset: offset,
                animated: true,
            });
        });
    }

    return (
        <View style={[StyleSheet.absoluteFill, styles.outerContainer]} key="legendlist">
            <LegendList
                ref={listRef}
                style={[StyleSheet.absoluteFill, styles.scrollContainer]}
                contentContainerStyle={styles.listContainer}
                data={data}
                renderItem={renderItem}
                keyExtractor={(item) => `id${item.id}`}
                estimatedItemSize={ESTIMATED_ITEM_LENGTH}
                drawDistance={DRAW_DISTANCE}
                maintainVisibleContentPosition
                recycleItems={true}
                ListHeaderComponent={<View />}
                ListHeaderComponentStyle={styles.listHeader}
                ListFooterComponent={<View />}
                ListFooterComponentStyle={styles.listHeader}
                ListEmptyComponentStyle={{ flex: 1 }}
                ListEmptyComponent={
                    <View style={styles.listEmpty}>
                        <Text style={{ color: "white" }}>Empty</Text>
                    </View>
                }
                onStartReached={(props) => {
                    console.log("onStartReached", props);
                }}
                onEndReached={(props) => {
                    console.log("onEndReached", props);
                }}
            />
        </View>
    );
}

const styles = StyleSheet.create({
    listHeader: {
        alignSelf: "center",
        height: 100,
        width: 100,
        backgroundColor: "#456AAA",
        borderRadius: 12,
        marginHorizontal: 8,
        marginVertical: 8,
    },
    listEmpty: {
        flex: 1,
        justifyContent: "center",
        alignItems: "center",
        backgroundColor: "#6789AB",
        paddingVertical: 16,
    },
    outerContainer: {
        backgroundColor: "#456",
        bottom: Platform.OS === "ios" ? 82 : 0,
    },
    scrollContainer: {},
    listContainer: {
        width: 360,
        maxWidth: "100%",
        marginHorizontal: "auto",
    },
});
```
